Lemma free_gap : forall (n : nat) (l : list (Z * Z)) (lo hi G : Z),
  length l = n -> 0 <= G -> Forall (fun e => 0 <= snd e) l ->
  (hi - lo) - zsizes l >= (Z.of_nat n + 1) * (G + 4095) ->
  exists g, g mod 4096 = 0 /\ lo <= g /\ g + G <= hi /\ Forall (fun e => g + G <= fst e \/ fst e + snd e <= g) l.
